from bioblend.galaxy import GalaxyInstance
import os, json
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
gi=GalaxyInstance(url=os.environ.get('GALAXY_URL','https://usegalaxy.org'), key=key)
tid='toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0'
# Print concise input names recursively
def walk(x, prefix=''):
    if isinstance(x, list):
        for v in x: walk(v,prefix)
    elif isinstance(x, dict):
        t=x.get('model_class') or x.get('type')
        name=x.get('name')
        print(prefix, t, name, 'value='+str(x.get('value')) if 'value' in x else '')
        for k in ('test_param','inputs'):
            if k in x:
                walk(x[k], prefix+'  '+k+':')
        for case in x.get('cases',[]) or []:
            print(prefix+'  case', case.get('value'))
            walk(case.get('inputs',[]), prefix+'    ')
tool=gi.tools.show_tool(tid, io_details=True)
walk(tool.get('inputs'))
PY"

